  "indicator_readings": [
    {
      "indicator": "Fechamento (preço)",
      "reading": "≈ R$13,1 (aprox.), em tentativa de recuperação curtíssima",
      "interpretation": "Preço próximo/um pouco acima da MM20 e das EMAs curtas, ainda abaixo da MM50 e da MM200 — recuperação técnica, não confirmação de tendência de fundo."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$12,9 (aprox.)",
      "interpretation": "MM20 abaixo da MM50 e MM200; curto prazo mostra pressão vendedora histórica, atua como referência de suporte/resistência de curto prazo."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$13,6 (aprox.)",
      "interpretation": "Média de médio prazo descendente; funciona como resistência imediata relevante para validar recuperação."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$15,0 (aprox.)",
      "interpretation": "Tendência de longo prazo ainda baixista (MM200 inclinada para baixo). Romper e segurar acima dela seria requisito para mudança estrutural."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$12,9 (aprox.), cruzando a EMA21",
      "interpretation": "Crossover favorável de curtíssimo prazo que indica melhoria momentânea do impulso, válido para trades táticos se confirmado."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$13,0 (aprox.)",
      "interpretation": "Próxima à EMA9 — confirmação dependente de continuidade e volume."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "Linha MACD próxima da linha de sinal; histograma pequeno positivo, ambos perto de zero",
      "interpretation": "Momentum virou levemente positivo no curtíssimo prazo, mas permanece fraco — precisa de confirmação com cruzamento robusto e aumento de histograma."
    },
    {
      "indicator": "Bandas de Bollinger (20, 2σ)",
      "reading": "Bandas estreitas recentemente, com leve alargamento na recuperação",
      "interpretation": "Volatilidade reduziu em agosto; a expansão atual pode preceder movimento direcional mais forte se acompanhado por volume."
    },
    {
      "indicator": "RSI (14)",
      "reading": "≈ 50 (aprox.), subiu desde níveis ~30",
      "interpretation": "RSI saiu de sobrevenda e está em zona neutra — sinal de melhora, porém sem sobrecompra que confirme força sustentada."
    },
    {
      "indicator": "Volume",
      "reading": "Volume recente moderado/baixo; picos em abr/mai durante a queda",
      "interpretation": "Recuperação atual tem volume tímido — falta confirmação volumétrica para validar rompimentos de resistência."
    }
  ]
